def metadata(doi: str):
    try:
        d=requests.get('https://api.crossref.org/works/'+doi, timeout=20, headers={'User-Agent':'LiteratureEvidenceMatrix/1.0 (academic research)'}).json()['message']
        authors=d.get('author',[])
        names=[]
        for a in authors:
            name=' '.join(filter(None,[a.get('given',''),a.get('family','')]))
            if name:names.append(name)
        y=(d.get('published-print') or d.get('published-online') or d.get('published') or d.get('issued') or {}).get('date-parts',[[None]])[0][0]
        return {'title':d.get('title',[''])[0], 'authors':', '.join(names), 'year':y, 'journal':d.get('container-title',[''])[0]}
    except Exception as e:
        return {'title':'[元数据待核]','authors':'[待核]','year':'[待核]','journal':'[待核]','error':str(e)}

def get_meta():
    cache=json.loads(CACHE.read_text(encoding='utf-8')) if CACHE.exists() else {}
    dois=[p[1] for p in PAPERS+YU if p[1] not in cache or cache[p[1]].get('error')]
    if dois:
        with ThreadPoolExecutor(max_workers=10) as pool:
            for doi, val in zip(dois,pool.map(metadata,dois)):
                cache[doi]=val
        CACHE.write_text(json.dumps(cache,ensure_ascii=False,indent=2),encoding='utf-8')
    return cache

def record(p, meta, yu=False):
    if yu:
        id,doi,parts,question,claim,kind,quant,fig,place,boundary,relation=p
    else:
        id,doi,category,question,claim,kind,quant,fig,place,boundary,relation,url=p
        parts={'引言背景与综述':'I','神经与心理物理':'II','电极皮肤界面':'II','系统集成与供能':'V'}[category]
    m=meta[doi]
    author=m['authors']
    lines=[f"### {id} {m['title']}",
      f"- **文献信息**：{author}；{m['year']}；*{m['journal']}*；[DOI: {doi}](https://doi.org/{doi})。",
      f"- **对应章节**：{parts}。",
      f"- **对应问题**：{question}。",
      f"- **核心结论**：{claim}。",
      f"- **证据类型**：{kind}。",
      f"- **关键定量结果**：{quant}。",
      f"- **值得查看的图表**：{fig}。",
      f"- **可用于本文的位置**：{place}。",
      f"- **证据边界**：{boundary}。",
      f"- **与于欣格课题组工作的关系**：{relation}。"]
    if not yu:lines.append(f"- **官方/开放全文入口**：[{url}]({url})。")
    return '\n'.join(lines)

